AttributeMapItem.Script:
ret.value = work.newAttribute("user.phone");

// need to convert the flat conn entry to a hierarchical one in order to work with
// phone's children as nodes of a tree.
conn.enableDOM();

for (phone in conn["user.phone"]) {
	if (phone.getClass().getSimpleName().equals("Attribute")) {
		// we found an attribute, most probably attribute named 1 or 2, just add its value to the result.
		ret.value.addValues(phone);
	} else {
		// simple AttributeValue or String just add it as value.
		ret.value.addValue(phone);
	}
}

Script.parameter:
// create an emtpy node.
var namespaceURI = "http://identity.namespaces.com/";
work["{" + namespaceURI + "}i:identity"] = null;

var identity = work["i:identity"];

// get the string representation of the user.id attribute and add it as property
identity["@i:id"] = work["user.id"].getValue();

// note that the namespace will be resolved automatically as the prefix has 
// already been defined by the "identity" element above.
identity["i:firstName"] = work["user.first"];
identity["i:lastName"] = work["user.last"];
identity["i:phones"] = null;

// the user.phone attribute is a multi-valued one and we want each value to be
// in its own element
for (phoneVal in work["user.phone"]) {
	phone = work.createElementNS(namespaceURI, "i:phone");
	phone.addValue(phoneVal);
	identity["i:phones"].appendChild(phone);
}
